function femmdata = read_femmdata(finfilename,readmesh)

% function femmdata = read_femmdata(finfilename,readmesh)
% reads all data provided in a .ans file generated by FEMM
%
% input parameters
%    finfilename      : file name or file pointer
%    readmesh         : [1/0] : read mesh or not (optional; default: 1)
%
% output parameter
%    femmdata : FEMM data

%% A. Parameter check
if ischar(finfilename)
    fin = fopen(finfilename,'r');
    if fin==-1
        error('Unable to open file ---%s---\n',finfilename);
    end
else
    fin = finfilename;
end
if ~exist('readmesh','var')
    readmesh = 1;
end
femmdata.datastructure = 'femm';

%% B. Determine physics type and determine particular column sizes
femmdata.physics_type = femm_determine_physics_type(finfilename);
switch femmdata.physics_type
    case 'magnetic'
        numcolsegments = 6;
        numcolarcsegments = 7;
        numcolpoints = 4;
    case 'electric'
        numcolsegments = 7;
        numcolarcsegments = 8;
        numcolpoints = 5;
    case 'electrokinetic'
        numcolsegments = 7;
        numcolarcsegments = 8;
        numcolpoints = 5;
    otherwise
        error('to be implemented');
end

%% C. Read everything
while ~feof(fin)
    ln = fgetl(fin);
    [first,ln] = strtok(ln);
    if ~isempty(first)
        [second,ln] = strtok(ln);
        [third,ln] = strtok(ln);
        if (first(1)=='[') && (first(end)==']')
            first = first(2:end-1);
        end
        if second=='='
            femmdata.(first) = third;
        end
        switch first
            case {'Depth'}                 % single double number
                femmdata.(first) = sscanf(femmdata.(first),'%f');
            case {'PointProps','BdryProps','BlockProps','CircuitProps','ConductorProps'}
                num=sscanf(femmdata.(first),'%d');
                if num==0
                    femmdata.(first) = [];
                else
                    femmdata = rmfield(femmdata,first);
                end
                for p=1:num
                    % D.1. Name
                    [subfirst,ln] = strtok(fgetl(fin));    % <BeginBdry>
                    if (subfirst(1)~='<') || (subfirst(end)~='>')
                        error('sth wrong1');
                    end
                    if (subfirst(2:6)~='Begin')
                        error('sth wrong2');
                    end
                    propname = subfirst(7:end-1);
                    [subfirst,ln] = strtok(fgetl(fin));
                    while ~strcmp(subfirst,['<End' propname '>'])
                        [subsecond,ln] = strtok(ln);
                        [subthird,ln] = strtok(ln);
                        if (subfirst(1)~='<') || (subfirst(end)~='>')
                            error('sth wrong3');
                        end
                        subfirst = subfirst(2:end-1);
                        if subsecond~='='
                            error('sth wrong4');
                        end
                        if ~strcmp(subfirst,'BHPoints')
                            femmdata.(first)(p).(subfirst) = subthird;
                        else
                            numBHpoint = sscanf(subthird,'%d');
                            BH = zeros(numBHpoint,2);
                            for qqq=1:numBHpoint
                                ln = fgetl(fin);
                                BH(qqq,:) = reshape(sscanf(ln,'%f %f'),1,2);
                            end
                            femmdata.(first)(p).BHPoints = BH;
                        end
                        [subfirst,ln] = strtok(fgetl(fin));
                    end
                end
            case 'NumPoints'
                numpoints = sscanf(femmdata.NumPoints,'%d');
                femmdata = rmfield(femmdata,'NumPoints');
                %femmdata.points = fscanf(fin,'%f',[numcolpoints numpoints])';
                femmdata.points = readarray(fin,numpoints,[],'%f');
            case 'NumSegments'
                numsegments = sscanf(femmdata.NumSegments,'%d');
                femmdata = rmfield(femmdata,'NumSegments');
                %femmdata.segments = fscanf(fin,'%f',[numcolsegments numsegments])';
                femmdata.segments = readarray(fin,numsegments,[],'%f');               
            case 'NumArcSegments'
                numarcsegments = sscanf(femmdata.NumArcSegments,'%d');
                femmdata = rmfield(femmdata,'NumArcSegments');
                %femmdata.arcsegments = fscanf(fin,'%f',[numcolarcsegments numarcsegments])';
                femmdata.arcsegments = readarray(fin,numarcsegments,[],'%f');
            case 'NumHoles'
                numholes = sscanf(femmdata.NumHoles,'%d');
                femmdata = rmfield(femmdata,'NumHoles');
                %femmdata.holes = fscanf(fin,'%f',[3 numholes])';
                femmdata.holes = readarray(fin,numholes,[],'%f');
            case 'NumBlockLabels'
                numblocklabels = sscanf(femmdata.NumBlockLabels,'%d');
                femmdata = rmfield(femmdata,'NumBlockLabels');
                %femmdata.blocklabels = fscanf(fin,'%f',[9 numblocklabels])';
                for i=1:numblocklabels
                    tline = fgetl(fin);
                    [femmdata.blocklabels(i,:),count,errmsg,nextindex] = sscanf(tline,'%f',9);
                    femmdata.magndir{i} = sscanf(tline(:,nextindex:end),'%s');
                end
            case 'Solution'
                if readmesh
                    femmdata.node = readarray(fin,[],[]);
%                     numnode = fscanf(fin,'%d',1);
%                     ln = fgetl(fin);                      % discard the line termination
%                     ln = fgetl(fin);                      % read the first line to check whether a real-valued or a complex-valued solution is given
%                     [values,num] = sscanf(ln,'%f');
%                     values = [values'; fscanf(fin,'%f',[num numnode-1])'];
%                     switch num
%                         case 3
%                             femmdata.node = values;
%                         case 4
%                             femmdata.node = [values(:,1:2) values(:,3)+sqrt(-1)*values(:,4)];
%                         case 5
%                             femmdata.node = [values(:,1:2) values(:,3)]; % anc-file
%                         otherwise
%                             error('format problem encountered in read_femm.m');
%                     end
                    if str2num(femmdata.Frequency)~=0  % combine column 3 and 4 in one complex number
                      femmdata.node = [ femmdata.node(:,1:2) complex(femmdata.node(:,3),femmdata.node(:,4)) femmdata.node(:,5:end) ];
                    end
                    femmdata.elem = readarray(fin,[],[]);
%                     numelem = fscanf(fin,'%d',1);
%                     femmdata.elem = fscanf(fin,'%d',[4 numelem])';
                    femmdata.whatisthis = fgetln(fin);
                    %femmdata.whatisthis = readarray(fin,[],[]);
%                     numwhatisthis = fscanf(fin,'%d',1);
%                     femmdata.whatisthis = fscanf(fin,'%d',[2 numwhatisthis])';
                end
        end
    end
end

% adapt indices (THIS HAS TO BE DONE OUTSIDE READ_FEMMDATA !!!
%femmdata.elem=femmdata.elem+1;
%femmdata.segments(:,1:2)=femmdata.segments(:,1:2)+1;
%femmdata.arcsegments(:,1:2)=femmdata.arcsegments(:,1:2)+1;

%% D. Finish
if ischar(finfilename)
    fclose(fin);
end

